    def repo_get_all_commits(self,
                             owner,
                             repo,
                             sha=None,
                             path=None,
                             since=None,
                             until=None,
                             stat=None,
                             verification=None,
                             files=None,
                             page=None,
                             limit=None,
                             mnot=None):
        """Perform a GET request to /repos/{owner}/{repo}/commits.

        Get a list of all commits from a repository

        Args:
            owner (str): owner of the repo
            repo (str): name of the repo
            sha (str, optional): SHA or branch to start listing commits from (usually
                'master')
            path (str, optional): filepath of a file/dir
            since (datetime, optional): Only commits after this date will be returned
                (ISO 8601 format)
            until (datetime, optional): Only commits before this date will be
                returned (ISO 8601 format)
            stat (bool, optional): include diff stats for every commit (disable for
                speedup, default 'true')
            verification (bool, optional): include verification for every commit
                (disable for speedup, default 'true')
            files (bool, optional): include a list of affected files for every commit
                (disable for speedup, default 'true')
            page (int, optional): page number of results to return (1-based)
            limit (int, optional): page size of results (ignored if used with 'path')
            mnot (str, optional): commits that match the given specifier will not be
                listed.

        Returns:
            ApiResponse: An object with the response value as well as other useful
                information such as status codes and headers. CommitList

        Raises:
            ApiException: When an error occurs while fetching the data from the
                remote API. This exception includes the HTTP Response code, an error
                message, and the HTTP body that was received in the request.

        """
        return super().new_api_call_builder.request(
            RequestBuilder().server(Server.SERVER1)
            .path("/repos/{owner}/{repo}/commits")
            .http_method(HttpMethodEnum.GET)
            .template_param(Parameter()
                .key("owner")
                .value(owner)
                .is_required(True)
                .should_encode(True))
            .template_param(Parameter()
                .key("repo")
                .value(repo)
                .is_required(True)
                .should_encode(True))
            .query_param(Parameter()
                .key("sha")
                .value(sha))
            .query_param(Parameter()
                .key("path")
                .value(path))
            .query_param(Parameter()
                .key("since")
                .value(APIHelper.when_defined(APIHelper.RFC3339DateTime,
                    since)))
            .query_param(Parameter()
                .key("until")
                .value(APIHelper.when_defined(APIHelper.RFC3339DateTime,
                    until)))
            .query_param(Parameter()
                .key("stat")
                .value(stat))
            .query_param(Parameter()
                .key("verification")
                .value(verification))
            .query_param(Parameter()
                .key("files")
                .value(files))
            .query_param(Parameter()
                .key("page")
                .value(page))
            .query_param(Parameter()
                .key("limit")
                .value(limit))
            .query_param(Parameter()
                .key("not")
                .value(mnot))
            .header_param(Parameter()
                .key("accept")
                .value("application/json"))
            .auth(Or(Single("BasicAuth"), Single("Token"),
                Single("AccessToken"), Single("AuthorizationHeaderToken"),
                Single("SudoParam"), Single("SudoHeader"), Single("TOTPHeader"))),
        ).response(
            ResponseHandler()
            .deserializer(APIHelper.json_deserialize)
            .deserialize_into(CommitContainsInformationGeneratedFromAGitCommit.from_dictionary)
            .is_api_response(True)
            .local_error("404",
                "APINotFound is a not found empty response",
                ApiException)
            .local_error("409", "EmptyRepository", ApiErrorException),
        ).execute()

