    def repo_get_contents_ext(self,
                              owner,
                              repo,
                              filepath,
                              ref=None,
                              includes=None):
        """Perform a GET request to
        /repos/{owner}/{repo}/contents-ext/{filepath}.

        It guarantees that only one of the response fields is set if the request
        succeeds. Users can pass "includes=file_content" or "includes=lfs_metadata"
        to retrieve more fields. "includes=file_content" only works for single file,
        if you need to retrieve file contents in batch, use "file-contents" API after
        listing the directory.

        Args:
            owner (str): owner of the repo
            repo (str): name of the repo
            filepath (str): path of the dir, file, symlink or submodule in the repo.
                Swagger requires path parameter to be "required", you can leave it
                empty or pass a single dot (".") to get the root directory.
            ref (str, optional): the name of the commit/branch/tag, default to the
                repository’s default branch.
            includes (str, optional): By default this API's response only contains
                file's metadata. Use comma-separated "includes" options to retrieve
                more fields. Option "file_content" will try to retrieve the file
                content, "lfs_metadata" will try to retrieve LFS metadata,
                "commit_metadata" will try to retrieve commit metadata, and
                "commit_message" will try to retrieve commit message.

        Returns:
            ApiResponse: An object with the response value as well as other useful
                information such as status codes and headers.

        Raises:
            ApiException: When an error occurs while fetching the data from the
                remote API. This exception includes the HTTP Response code, an error
                message, and the HTTP body that was received in the request.

        """
        return super().new_api_call_builder.request(
            RequestBuilder().server(Server.SERVER1)
            .path("/repos/{owner}/{repo}/contents-ext/{filepath}")
            .http_method(HttpMethodEnum.GET)
            .template_param(Parameter()
                .key("owner")
                .value(owner)
                .is_required(True)
                .should_encode(True))
            .template_param(Parameter()
                .key("repo")
                .value(repo)
                .is_required(True)
                .should_encode(True))
            .template_param(Parameter()
                .key("filepath")
                .value(filepath)
                .is_required(True)
                .should_encode(True))
            .query_param(Parameter()
                .key("ref")
                .value(ref))
            .query_param(Parameter()
                .key("includes")
                .value(includes))
            .header_param(Parameter()
                .key("accept")
                .value("application/json"))
            .auth(Or(Single("BasicAuth"), Single("Token"),
                Single("AccessToken"), Single("AuthorizationHeaderToken"),
                Single("SudoParam"), Single("SudoHeader"), Single("TOTPHeader"))),
        ).response(
            ResponseHandler()
            .deserializer(APIHelper.json_deserialize)
            .deserialize_into(ContentsExtResponse.from_dictionary)
            .is_api_response(True)
            .local_error("404",
                "APINotFound is a not found empty response",
                ApiException),
        ).execute()

