    def repo_tracked_times(self,
                           owner,
                           repo,
                           user=None,
                           since=None,
                           before=None,
                           page=None,
                           limit=None):
        """Perform a GET request to /repos/{owner}/{repo}/times.

        List a repo's tracked times

        Args:
            owner (str): owner of the repo
            repo (str): name of the repo
            user (str, optional): optional filter by user (available for issue
                managers)
            since (datetime, optional): Only show times updated after the given time.
                This is a timestamp in RFC 3339 format
            before (datetime, optional): Only show times updated before the given
                time. This is a timestamp in RFC 3339 format
            page (int, optional): page number of results to return (1-based)
            limit (int, optional): page size of results

        Returns:
            ApiResponse: An object with the response value as well as other useful
                information such as status codes and headers. TrackedTimeList

        Raises:
            ApiException: When an error occurs while fetching the data from the
                remote API. This exception includes the HTTP Response code, an error
                message, and the HTTP body that was received in the request.

        """
        return super().new_api_call_builder.request(
            RequestBuilder().server(Server.SERVER1)
            .path("/repos/{owner}/{repo}/times")
            .http_method(HttpMethodEnum.GET)
            .template_param(Parameter()
                .key("owner")
                .value(owner)
                .is_required(True)
                .should_encode(True))
            .template_param(Parameter()
                .key("repo")
                .value(repo)
                .is_required(True)
                .should_encode(True))
            .query_param(Parameter()
                .key("user")
                .value(user))
            .query_param(Parameter()
                .key("since")
                .value(APIHelper.when_defined(APIHelper.RFC3339DateTime,
                    since)))
            .query_param(Parameter()
                .key("before")
                .value(APIHelper.when_defined(APIHelper.RFC3339DateTime,
                    before)))
            .query_param(Parameter()
                .key("page")
                .value(page))
            .query_param(Parameter()
                .key("limit")
                .value(limit))
            .header_param(Parameter()
                .key("accept")
                .value("application/json"))
            .auth(Or(Single("BasicAuth"), Single("Token"),
                Single("AccessToken"), Single("AuthorizationHeaderToken"),
                Single("SudoParam"), Single("SudoHeader"), Single("TOTPHeader"))),
        ).response(
            ResponseHandler()
            .deserializer(APIHelper.json_deserialize)
            .deserialize_into(TrackedTime.from_dictionary)
            .is_api_response(True)
            .local_error("400", "APIError is error format response", ApiException)
            .local_error("403",
                "APIForbiddenError is a forbidden error response",
                ApiException)
            .local_error("404",
                "APINotFound is a not found empty response",
                ApiException),
        ).execute()

